/* Доля карт Story Spotlight без текстового блока (istextless = 0) от общего числа карт */
SELECT
    /* Процент: карты Story Spotlight без текста / все карты * 100 */
    (SUM(CASE WHEN "isstoryspotlight" = 1 AND "istextless" = 0 THEN 1 ELSE 0 END)::numeric
     / NULLIF(COUNT(*), 0)) * 100 AS percentage,
    /* Список ID таких карт */
    STRING_AGG(
        CASE WHEN "isstoryspotlight" = 1 AND "istextless" = 0
             THEN "id"::text END,
        ', ' ORDER BY "id"
    ) AS story_spotlight_textless_ids
FROM "cards";
